CREATE TABLE "Profile" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "email" TEXT, "location" TEXT, "githubUrl" TEXT, "gitlabUrl" TEXT, "websiteUrl" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Profile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Skill" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "category" TEXT, "level" TEXT, "profileId" TEXT NOT NULL, CONSTRAINT "Skill_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Experience" ("id" TEXT NOT NULL, "company" TEXT NOT NULL, "position" TEXT NOT NULL, "location" TEXT, "startDate" TIMESTAMP(3) NOT NULL, "endDate" TIMESTAMP(3), "isCurrent" BOOLEAN NOT NULL DEFAULT false, "description" TEXT, "achievements" TEXT[], "profileId" TEXT NOT NULL, CONSTRAINT "Experience_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Project" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "url" TEXT, "repositoryUrl" TEXT, "technologies" TEXT[], "authors" TEXT[], "featured" BOOLEAN NOT NULL DEFAULT false, "status" TEXT, "releaseDate" TIMESTAMP(3), "profileId" TEXT NOT NULL, CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Skill_profileId_name_key" ON "Skill"("profileId", "name");
CREATE INDEX "Skill_profileId_idx" ON "Skill"("profileId");
CREATE INDEX "Experience_profileId_startDate_idx" ON "Experience"("profileId", "startDate");
CREATE INDEX "Project_profileId_idx" ON "Project"("profileId");
ALTER TABLE "Skill" ADD CONSTRAINT "Skill_profileId_fkey" FOREIGN KEY ("profileId") REFERENCES "Profile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Experience" ADD CONSTRAINT "Experience_profileId_fkey" FOREIGN KEY ("profileId") REFERENCES "Profile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Project" ADD CONSTRAINT "Project_profileId_fkey" FOREIGN KEY ("profileId") REFERENCES "Profile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
